"""Build the explicit lung-only gateway for shared pembrolizumab regimen assets."""
from pathlib import Path
import json,html
R=Path(__file__).resolve().parents[1]
for c in ['00455','00558']:
 d=json.loads((R/f'data/patient-knowledge/{c}.json').read_text());esc=html.escape
 body=f'''<!doctype html><html lang="en-IE"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>Choose the pembrolizumab treatment context · NCCP {c} · SACTCheck</title><link rel="stylesheet" href="../../assets/patient/patient-regimen-page-v0819.css"><link rel="stylesheet" href="../../assets/patient/patient-knowledge.css"></head><body><main class="pk-shell"><section class="pk-section"><div class="pk-eyebrow">Pembrolizumab · NCCP {c}</div><h1>Match the information to your treatment.</h1><p>Pembrolizumab is used for several cancers. These patient materials cover non-small-cell lung cancer (NSCLC) only. Your team confirms which setting applies.</p><article class="pk-card"><h2>Lung cancer: advanced disease or treatment after surgery</h2><p>The materials distinguish treatment for advanced lung cancer from adjuvant treatment after surgery and chemotherapy. The eligibility, aim and planned duration are different. An adjuvant time limit must not be applied to advanced disease.</p><a class="pk-button" id="lung-material" href="./">Open the lung treatment information</a></article><article class="pk-card"><h2>Another cancer or a combination regimen</h2><p>These lung monotherapy materials do not cover other cancers or pembrolizumab combined with chemotherapy. Use the matching regimen and indication and ask the treating team for the individual plan.</p><a href="{esc(d['sources'][0]['url'])}">Open the shared NCCP pembrolizumab regimen</a></article><p>{esc(d['review_status'])} · SACTCheck v0.84.22</p><p><a href="../../">Return to SACTCheck</a></p></section></main><script src="../../assets/patient/lung-indication-scope-v08422.js"></script></body></html>\n'''
 (R/f'patient/{c}/scope.html').write_text(body)
